const fetchData = async () => {
  try {
    if (!staffProfile) {
      setStores([]);
      setSelectedStoreId('');
      return;
    }

    const fetchedStores = isAdmin
      ? (await getDocs(collection(db, 'stores'))).docs.map(d => ({ id: d.id, ...d.data() } as Store))
      : (await Promise.all(
        assignedStoreIdentifiers(staffProfile)
          .map((storeId) => getDoc(doc(db, 'stores', storeId)).catch(() => null)),
      ))
        .filter((snap): snap is NonNullable<typeof snap> => !!snap && snap.exists())
        .map((snap) => ({ id: snap.id, ...snap.data() } as Store));

    const allowedStores = accessiblePosStores(fetchedStores, staffProfile);

    setStores(allowedStores);
    if (allowedStores.length > 0) {
      setSelectedStoreId(allowedStores[0].id);
    } else {
      setSelectedStoreId('');
    }
  } catch (error: any) {
    if (error?.code !== 'permission-denied') {
      console.error("Error fetching POS data:", error);
    }
  }
};

normalizePrepStation:
function normalizePrepStation(value: unknown): PrepStation {
  const normalized = String(value || 'NONE').trim().toUpperCase().replace(/[\s-]+/g, '_');
  if (normalized === 'BARISTA' || normalized === 'BAR') return 'BARISTA';
  if (normalized === 'KITCHEN' || normalized === 'KITCHEN_KOT') return 'KITCHEN';
  if (normalized === 'BOTH' || normalized === 'BARISTA_KITCHEN' || normalized === 'BAR_AND_KITCHEN') return 'BOTH';
  return 'NONE';
}
